    H,W=len(g),len(g[0])
    bg=max([v for row in g for v in row],key=lambda v:sum(row.count(v) for row in g))
    seen=set(); out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg and (r,c) not in seen:
                col=g[r][c]; st=[(r,c)]; seen.add((r,c)); cells=set()
                while st:
                    y,x=st.pop(); cells.add((y,x))
                    for dy,dx in ((1,0),(0,1)):
                        n=(y+dy,x+dx)
                        if 0<=n[0]<H and 0<=n[1]<W and n not in seen and g[n[0]][n[1]]==col:
                            seen.add(n); st.append(n)
                ys=[p[0] for p in cells]; xs=[p[1] for p in cells]
                norm=tuple(sorted((y-min(ys),x-min(xs)) for y,x in cells))
                out.append({'col':col,'cells':frozenset(cells),'n':len(cells),'r0':min(ys),'r1':max(ys),'c0':min(xs),'c1':max(xs)})
    return out,bg
